age=[['Минуты — часы','DWI часто↑, ADC↓; FLAIR может быть без убедительных изменений.','Нормальная DWI возможна; FLAIR не точные часы.'],['Первые дни, примерно 1–7','Обычно DWI↑ / ADC↓, нарастающий T2/FLAIR-сигнал и отёк.','После реперфузии эволюция может отличаться.'],['Вторая неделя, примерно 7–14 дней','ADC может псевдонормализоваться, затем повышается; DWI ещё↑.','Не принимать нормальный ADC за отсутствие инфаркта.'],['Позднее: недели — месяцы','ADC↑, глиоз / потеря объёма / энцефаломаляция; DWI вариабельна.','Сроки перекрываются; описывать признаки, не назначать точную дату.']]
ht=[['HI1','Мелкие петехии по краям инфаркта.','Нет масс-эффекта от крови.'],['HI2','Более сливные петехии в зоне инфаркта.','Нет масс-эффекта от крови.'],['PH1','Сгусток / гематома ≤30% площади зоны инфаркта.','Небольшой масс-эффект.'],['PH2','Сгусток / гематома >30% зоны инфаркта.','Выраженный масс-эффект; ECASS I также относил сюда удалённый сгусток.']]
def table(rows,heads):return '<div class="tableWrap"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in heads)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+v+('</th>' if i==0 else '</td>') for i,v in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'
